/**
 * Builds the labeled photo pairs the damage-check eval runs on.
 *
 * Every pair is a check-out photo and a check-in photo of the same rental
 * item, with ground truth for what actually changed:
 *
 *   - Base scenes are generated by a Gemini image model (no licensing issues,
 *     labelled "AI-generated" wherever they are shown).
 *   - "changed" pairs ask the image model to remove an accessory or add
 *     damage, then apply a small lighting/pose shift so the two photos look
 *     like two separate sessions at the counter.
 *   - "unchanged" pairs (hard negatives) apply only lighting, pose, dust or
 *     glare changes in code, so the truth is known exactly: nothing changed.
 *
 *   npm run eval:pairs            # create anything missing
 *   npm run eval:pairs -- --force # regenerate everything
 */
import { GoogleGenAI, Modality } from "@google/genai";
import { existsSync } from "node:fs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

const ROOT = path.resolve("eval");
const IMAGES = path.join(ROOT, "images");
const IMAGE_MODEL = process.env.GEMINI_IMAGE_MODEL || "gemini-3-pro-image";
const force = process.argv.includes("--force");

const STYLE =
  "A realistic, slightly imperfect smartphone photo taken by a rental shop employee at the check-in counter, " +
  "on a plain matte light-grey counter mat, soft even overhead light. Products have no brand names, no logos and " +
  "no readable text. No people, no hands, no watermark.";

type Scene = { id: string; prompt: string };

